window.DIGEST.news.push(...[{"headline": "Perplexity Launches Fully Local AI Agent on Macs", "meta": "Today's News · 8 hours ago · News · 869 posts (fresher 9 hours ago on center column at reload)", "url": "https://x.com/i/trending/2112604711291400455", "summary": "RECOVER_FROM_PRIOR_SESSION_ONLY — X's Grok summary was captured in the prior session but was not re-read in this run. The trend was surfaced in the Today's News sidebar (news_sidebar_article_QWlUcmVuZDoyMTEyNjA0NzExMjkxNDAwNDU1) and not reopened here. Re-capture recommended on next fire by opening https://x.com/i/trending/2112604711291400455 and reading the 'Summary of this trend' / 'What's happening' block.", "posts": [{"id": "2112583333825950207", "url": "https://x.com/AravSrinivas/status/2112583333825950207", "text": "You can now run Perplexity Computer fully local on your Mac with no cloud based inference, without WiFi too. Enjoy!", "name": "Aravind Srinivas", "handle": "AravSrinivas", "avatar": "https://pbs.twimg.com/profile_images/2099903483457703936/U-W6QQk__200x200.jpg", "likes": 2049, "rts": 124, "replies": 138, "views": 147367, "ts": 1792514091, "media": [], "quote": {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}], "notes": "Only 2 of 3 top-post status URLs captured (third still needed — e.g. a @testingcatalog or @engadget status URL previously visible on the trend page). Summary not re-verified in this run.", "captured": 1792550214, "post_ids": ["2112583333825950207", "2112571597798461920"]}, {"headline": "DeepSeek open-sources DeepInfer inference framework, powers DeepSeek-V4.1-Flash", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=DeepSeek&src=trend_click&vertical=trends", "summary": "", "posts": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112627168861892882", "url": "https://x.com/MTSlive/status/2112627168861892882", "text": "SITUATION EXPLAINED: DeepSeek just open-sourced the engine that runs its AI, something OpenAI and Anthropic haven't done.\n\n• DeepInfer powers DeepSeek V4.1 Flash, which costs $0.30 per million input tokens and $1.20 per million output, and it's now open source under Apache 2.0\n• Inference is running a trained model, and serving a 552B-parameter one fast and cheap to millions of users is one of AI's hardest engineering problems\n• It spreads users, long prompts, and expert sub-networks across GPUs, and uses speculative decoding, where a small model guesses ahead and the big one checks\n• It only runs on Nvidia Blackwell GPUs and Huawei Ascend 950 chips, so it's built for data centers, not home rigs\n• It still leaves out the KV cache system and prefill/decode disaggregation, so it's not a full serving stack\n\n@theojaffee: \"DeepSeek open sources almost everything. It's really incredible. They release their model weights. They write papers explaining in detail their model architecture. They put out GitHub repos with their inference framework. DeepSeek really cares about fully open AGI in a way that other companies don't.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 57, "rts": 7, "replies": 2, "views": 6171, "ts": 1792524542, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112625434680758272/vid/avc1/640x360/vRUdLgo5Qv8CP0Fy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112625434680758272/vid/avc1/1280x720/iDhu1gO1dNlkKDvA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112625434680758272/img/LncNlUuo4Lg8jPf4.jpg", "dur": 695}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112471106426900677", "url": "https://x.com/tianyi/status/2112471106426900677", "text": "DeepSeek just open sourced its high-performance, large-scale inference framework DeepInfer in Apache-2.0 license.\n\nhttps://github.com/deepseek-ai/DeepInfer\n\nSupported features:\n\n- Optimized kernels, model and sampler runtime\n- Parallelism: Attention DP / balanced CP, MoE EP + EPLB\n- DSpark and confidence-scheduled verification\n- SWA bounded replay\n- Asynchronous scheduling (zero-overhead batch scheduler)\n- Batch-invariant inference\n- Deterministic sampling\n- Structured output", "name": "Tianyi Cui", "handle": "tianyi", "avatar": "https://pbs.twimg.com/profile_images/378800000650737082/b849b67d6470fafe8b3deb2ae97acfda_200x200.jpeg", "likes": 2486, "rts": 199, "replies": 201, "views": 264168, "ts": 1792487334, "media": [], "quote": null, "reply_to": null}], "captured": 1792547114, "post_ids": ["2112476496283775135", "2112627168861892882", "2112471106426900677"]}, {"headline": "Elon Musk Discusses AI Risks, Wealth, and a Money-Free Future", "meta": "Explore · Trending · News · 1.8K posts", "url": "https://x.com/i/trending/2112604714332250325", "summary": "In the debut episode of 'The Builders' podcast released October 20, Musk explained his fortune will mostly fund multi-planetary life, sustainable energy, and space expansion after taxes. He predicted a post-AI world where money fades, replaced by measures like energy and mass, while superintelligent AI with robots could add $30 trillion yearly to Earth's economy. Musk admitted trying to slow AI but accelerating it instead, warning humans may lose control to digital minds a million times smarter—hoping they stay kind.", "posts": [{"id": "2112599662192714215", "url": "https://x.com/WatcherGuru/status/2112599662192714215", "text": "JUST IN: Elon Musk says money will become \"irrelevant\" in the future, with energy and resources becoming the new measures of wealth.", "name": "Watcher.Guru", "handle": "WatcherGuru", "avatar": "https://pbs.twimg.com/profile_images/1641221212578754562/DfiC0KW2_200x200.png", "likes": 9083, "rts": 909, "replies": 1151, "views": 870796, "ts": 1792517984, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF2MXBXcAADJKr.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVF2MWZXgAAT1m1.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112551927649018058", "url": "https://x.com/SawyerMerritt/status/2112551927649018058", "text": "Elon Musk in new interview with Walter Isaacson on the wealth he's created:\n\n\"A fundamental misunderstanding of economics arises because of conflating resource allocation and consumption; I've created. My so-called wealth is simply a percentage ownership in SpaceX and Tesla. And this is going to be taxed quite heavily, and there's not some magical way to avoid taxes. If there were I would know about it. At the end of the day, this will get whittled down, and a few generations from now, if money still matters, which I don't think it will, my descendants would have a tiny fraction of what I have.\"", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 3053, "rts": 359, "replies": 204, "views": 3126536, "ts": 1792506603, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112550486775574528/vid/avc1/720x740/IVY-zfHHYhRmL9g6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112550486775574528/vid/avc1/1048x1080/ZUgkMG4w60plxaPE.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112550486775574528/img/vJQOpt-2OGMjqNBW.jpg", "dur": 97}], "quote": null, "reply_to": null}, {"id": "2112588436846911907", "url": "https://x.com/cb_doge/status/2112588436846911907", "text": "BREAKING: Elon Musk says money will become irrelevant and future currency will be measured in power, mass and energy.\n\n“I think currency will be measured in fundamental physics metrics like, you know, power, like wattage and tonnage, mass and energy.”", "name": "DogeDesigner", "handle": "cb_doge", "avatar": "https://pbs.twimg.com/profile_images/1498070100393754625/C2V-fbll_200x200.jpg", "likes": 2357, "rts": 384, "replies": 261, "views": 576479, "ts": 1792515307, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588200124510209/vid/avc1/1280x720/fbH3yXW-3G3eR0pM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588200124510209/vid/avc1/1920x1080/Ba8KjUKwiuRecQ9F.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588200124510209/img/knVRjKgwnSmZEInn.jpg", "dur": 224}], "quote": null, "reply_to": null}], "scope_note": "AI-frontier/safety-adjacent via the AI-risks framing, but substantive focus is on Musk's wealth/money-fading speculation; borderline keep per user scope.", "captured": 1792523701, "post_ids": ["2112599662192714215", "2112551927649018058", "2112588436846911907"]}, {"headline": "Ornith-1.5-122B frontier MoE model launch", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=Ornith-1.5-122B&src=trend_click&vertical=trends", "summary": "Ornith announced open-weight Ornith-1.5-122B MoE, strong and fast, runs on a single DGX card, on Ollama.", "posts": [{"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112565065958449435", "url": "https://x.com/ollama/status/2112565065958449435", "text": "Ornith 1.5 122B is available on Ollama! Run it all locally on your device. \n\nollama run ornith-1.5:122b", "name": "ollama", "handle": "ollama", "avatar": "https://pbs.twimg.com/profile_images/2045273960666071040/rCjCIwiC_200x200.jpg", "likes": 311, "rts": 28, "replies": 24, "views": 23799, "ts": 1792509735, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086790, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792545066, "post_ids": ["2112553477457268799", "2112565065958449435"]}, {"headline": "TypeScript", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=TypeScript&src=trend_click&vertical=trends", "summary": null, "summary_note": "TypeScript is a keyword trend (Technology · Trending), not a news story — X opens a search results page with no Grok summary blurb. Top results center on TypeScript 7.1 Beta launch and dev-tool news.", "posts": [{"id": "2112610990202507582", "url": "https://x.com/typescript/status/2112610990202507582", "text": "TypeScript 7.1 Beta is now available! Now with a preview API, content mapper support, new features, and some great optimizations. Give it a try and give us some feedback! https://devblogs.microsoft.com/typescript/announcing-typescript-7-1-beta/", "name": "TypeScript", "handle": "typescript", "avatar": "https://pbs.twimg.com/profile_images/1648471227416346625/v84A9gXA_200x200.png", "likes": 994, "rts": 125, "replies": 27, "views": 72083, "ts": 1792520685, "media": [], "quote": null, "reply_to": null}, {"id": "2112644617141371061", "url": "https://x.com/cline/status/2112644617141371061", "text": "Use the Goal plugin in Cline Desktop to keep Cline working until the task is verified complete.\n\nCustomize > Marketplace > Plugins > Install 'Goal' > use /goal\n\nPlugins are TypeScript files that extend Cline's capabilities with:\n- Slash commands\n- Custom tools\n- Lifecycle hooks (beforeTool, afterRun, etc.)\n- Dynamic rules\n\nThe Goal plugin adds a /goal slash command and an afterRun hook that nudges Cline to verify its work, and only when verified complete can it call the plugin's custom mark_goal_complete tool to finish the task.", "name": "Cline", "handle": "cline", "avatar": "https://pbs.twimg.com/profile_images/2100371495658946560/pKjt1-8w_200x200.png", "likes": 62, "rts": 4, "replies": 8, "views": 4138, "ts": 1792528702, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112643720885772289/vid/avc1/1152x720/o7K8tNBVSeNiyl3s.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112643720885772289/vid/avc1/1920x1200/NMI4gESesAIDByVL.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112643720885772289/img/snGi89hJ6QKc9jqZ.jpg", "dur": 18}], "quote": null, "reply_to": null}, {"id": "2112531443591020965", "url": "https://x.com/voidzerodev/status/2112531443591020965", "text": "Introducing tsrs: a Rust port of the TypeScript compiler 🦀\n\nWe are not forking TypeScript!\n\n◆ In close collaborating with the TypeScript team\n◆ Up to 8x faster than TS 7.0 & ~70% less memory\n◆ Runs in WASM, so it works in your browser & on Workers\n◆ Soon part of the Oxc toolchain\n\nnpx tsrs\n\nhttps://blog.cloudflare.com/typescript-rust-port%20%20/", "name": "VoidZero", "handle": "voidzerodev", "avatar": "https://pbs.twimg.com/profile_images/2011008157888159744/bTvdh1Nd_200x200.jpg", "likes": 4329, "rts": 467, "replies": 129, "views": 460890, "ts": 1792501719, "media": [], "quote": null, "reply_to": null}], "captured": 1792559277, "post_ids": ["2112610990202507582", "2112644617141371061", "2112531443591020965"]}, {"headline": "Gradium Open-Sources Phonon: Sub-50M On-Device TTS Models Under Apache 2.0", "meta": "Explore · Trending · Technology · Trending · Apache 2.0", "url": "https://x.com/search?q=Apache+2.0&src=trend_click&vertical=trends", "summary": "The Apache 2.0 keyword trend is led by Gradium (@GradiumAI, 3h ago) open-sourcing Phonon, a suite of text-to-speech models under 50M parameters for on-device speech. Lead post: 'A new frontier for on-device speech. We're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date. Phonon-31m is available under Apache 2.0.' Link: gradium.ai/phonon. Stats: 80 replies, 205 reposts, 766 likes, ~87,678 views. The trend's second post, Ruben (@rdominguezibar, 18h ago), reports KingKong (a Beijing servos/encoders company) open-sourced under Apache 2.0 the software that teaches its crab robot 'Jumper' (22 joints, 1.8 kg) to move, on GitHub, shipping a CLAUDE.md to be opened in a coding agent. A third top post, Respan (@RespanAI, 2h ago), announced 'Respan OSS Gateway: the last AI gateway you ever need' connecting LLMs, images, video, realtime voice, and MCP tools like web search and long-term memory through one endpoint, each as a plugin. A fourth notable mention: Dean W. Perkins (@deanwperkins, 2h ago) noted a 31M-param TTS model (Phonon) now runs inside a browser extension — highlight text, hit Read, speaks it back word by word, no API key, no GPU, no internet round-trip, Apache 2.0. Note: keyword trend chip → search feed; summary built from lead posts. Kept on Gradium Phonon (AI creative tool / on-device / open-source TTS).", "posts": [{"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, {"id": "2112342171118358679", "url": "https://x.com/rdominguezibar/status/2112342171118358679", "text": "KingKong, a Beijing company that makes servos and encoders, put the software that teaches its crab robot Jumper to move on GitHub, free under Apache 2.0.\n\nThe robot has 22 joints and weighs 1.8 kg. The repo ships with a CLAUDE.md, built to be opened in a coding agent where you describe a new look or scene in one sentence.\n\nIt passed 2,385 stars in its first two weeks.", "name": "Ruben", "handle": "rdominguezibar", "avatar": "https://pbs.twimg.com/profile_images/2028166352704540672/p9vRZh5r_200x200.jpg", "likes": 7, "rts": 2, "replies": 1, "views": 1598, "ts": 1792456593, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112342143918387200/pu/vid/avc1/636x360/hYWDS_5yVYBTLNwT.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112342143918387200/pu/vid/avc1/1272x720/oRqkj-Sa1hLPCWFI.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112342143918387200/pu/img/5GJygzBQyQ-rzrGj.jpg", "dur": 15}], "quote": null, "reply_to": null}, {"id": "2112589739752837309", "url": "https://x.com/RespanAI/status/2112589739752837309", "text": "Respan OSS Gateway: the last AI gateway you ever need.\n\nBecause it can connect anything: LLMs, images, video, realtime voice, and MCP tools like web search and long-term memory, all through one endpoint. Each one is just a plugin you switch on.\n\nAgainst LiteLLM on the same machine:\n - 0.08 ms vs 5.9 ms added latency (78x less)\n - 61,062 vs 1,348 requests/s with 50 in flight (45x more; LiteLLM on 14 workers)\n - 33 MB vs 494 MB memory (15x less; LiteLLM on 1 worker)\n\nFully written in Rust. MIT/Apache-2.0.", "name": "Respan", "handle": "RespanAI", "avatar": "https://pbs.twimg.com/profile_images/2027070589756940288/1tWZSpNu_200x200.jpg", "likes": 129, "rts": 18, "replies": 17, "views": 10341, "ts": 1792515618, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1280x720/Vcevcs1-ZMZLV7oo.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1920x1080/o7SYrt6EbEVRDm_V.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589708589158400/img/BRkz-jytt9YRMCOW.jpg", "dur": 30}], "quote": null, "reply_to": null}], "captured": 1792523701, "post_ids": ["2112563128487514512", "2112342171118358679", "2112589739752837309"]}, {"headline": "Beacon Brings Memory Across AI Coding Tools with $5.5M Seed", "meta": "Today's News · Trending now · 743 posts", "url": "https://x.com/i/trending/2112622379822452799", "summary": "Asymptote Labs launched Beacon, an open-source memory layer recording prompts, edits and debugging from Claude Code and Cursor into reusable skills across 20+ agent systems; $5.5M seed led by Tower Research Ventures.", "posts": [{"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425937, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, {"id": "2112566864840917331", "url": "https://x.com/aibytekat/status/2112566864840917331", "text": "POV: you’re explaining your project to a new agent for the 47th time.\n\nMeanwhile Beacon, who already knows everything we tried 👇", "name": "Katyayani Shukla", "handle": "aibytekat", "avatar": "https://pbs.twimg.com/profile_images/1968767882776469504/qN_Wuv_4_200x200.jpg", "likes": 181, "rts": 83, "replies": 21, "views": 107006, "ts": 1792510164, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112565790012792832/vid/avc1/1280x720/veIESh221UPl0Dlq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112565790012792832/vid/avc1/1920x1080/EP9oCvIx6fY47edA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112565790012792832/img/h2e8A04cWGfc5OJz.jpg", "dur": 12}], "quote": {"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425836, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792527238, "post_ids": ["2112552451547001218", "2112566864840917331"]}, {"headline": "SophontAI Launches Holon-S1 to Predict Gene Activity from Cancer Slides", "meta": "Today's News · Trending now · News · 210 posts", "url": "https://x.com/i/trending/2112628194138280144", "summary": "Holon-S1 maps gene activity and pathways from routine H&E slides across 16 organ types; research only.", "posts": [{"id": "2112597012088844407", "url": "https://x.com/iScienceLuvr/status/2112597012088844407", "text": "Cancer patients with the same diagnosis often have very different tumor biology.\n\nMolecular testing can reveal underlying differences, but that's slow and expensive.\n\nIntroducing Holon-S1, our platform to predict genes and biomarkers from routine pathology slides.\n\n• beats two other models at predicting spatial gene activity in a controlled comparison\n• has identified potentially novel biomarkers in breast cancer and colon cancer\n• evaluated across 16 organ types and more than 15 scanners, using slides from both formalin-fixed, paraffin-embedded and fresh-frozen tissue.\n\nWe believe Holon-S1 has the potential to help researchers find new biomarkers in slides they already have, discover treatment targets, and bring more personalized cancer care within reach!", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 1794, "rts": 229, "replies": 132, "views": 128592, "ts": 1792517352, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1280x720/MhpKZm8hwCxP1y-o.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1920x1080/Hf7kqIlrKb8yWsW3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590555838644224/img/4T9V1b24pSfXPkcF.jpg", "dur": 213}], "quote": null, "reply_to": null}, {"id": "2112606895509012618", "url": "https://x.com/humanscotti/status/2112606895509012618", "text": "We've been training pathology and neuro foundation models at Sophont for a year now, and the pathology work is now good enough for real cancer research\n\nUsing routine tissue slides nearly all cancer patients already have, we predict spatially resolved genes and infer biological pathway activity\n\nHence, more cancer patients can have their tumors' biology molecularly interpreted to assess treatment options & discover biomarkers, which unfortunately isn't typically performed in routine standard of care\n\nLooking forward to working with research teams to actually deploy the fruits of our research to cancer patients", "name": "Paul Scotti", "handle": "humanscotti", "avatar": "https://pbs.twimg.com/profile_images/913730123811233793/zbaqQsQE_200x200.jpg", "likes": 86, "rts": 5, "replies": 10, "views": 3410, "ts": 1792519708, "media": [], "quote": {"id": "2112597012088844407", "url": "https://x.com/iScienceLuvr/status/2112597012088844407", "text": "Cancer patients with the same diagnosis often have very different tumor biology.\n\nMolecular testing can reveal underlying differences, but that's slow and expensive.\n\nIntroducing Holon-S1, our platform to predict genes and biomarkers from routine pathology slides.\n\n• beats two other models at predicting spatial gene activity in a controlled comparison\n• has identified potentially novel biomarkers in breast cancer and colon cancer\n• evaluated across 16 organ types and more than 15 scanners, using slides from both formalin-fixed, paraffin-embedded and fresh-frozen tissue.\n\nWe believe Holon-S1 has the potential to help researchers find new biomarkers in slides they already have, discover treatment targets, and bring more personalized cancer care within reach!", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 1794, "rts": 229, "replies": 132, "views": 128556, "ts": 1792517352, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1280x720/MhpKZm8hwCxP1y-o.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1920x1080/Hf7kqIlrKb8yWsW3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590555838644224/img/4T9V1b24pSfXPkcF.jpg", "dur": 213}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792529266, "post_ids": ["2112597012088844407", "2112606895509012618"]}, {"headline": "DeepSeek Opens DeepInfer Inference Framework (Powering DeepSeek-V4.1-Flash)", "meta": "Explore · Trending · Technology · DeepSeek", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "summary": "DeepSeek open-sourced DeepInfer, its in-house inference framework behind DeepSeek-V4.1-Flash (Apache 2.0); vLLM thanked DeepSeek.", "posts": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112480719952138301", "url": "https://x.com/vllm_project/status/2112480719952138301", "text": "Grateful to @deepseek_ai for releasing DeepInfer, initially built primarily on @vllm_project, under Apache 2.0 and crediting the open-source community!\n\nWe've worked hard on DeepSeek V4.1 Flash inference efficiency and will keep improving with ideas from DeepInfer! Stay tuned 🙌", "name": "vLLM", "handle": "vllm_project", "avatar": "https://pbs.twimg.com/profile_images/1774187681746182144/N_5NJ8B1_200x200.jpg", "likes": 2112, "rts": 121, "replies": 51, "views": 69495, "ts": 1792489626, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEJ3G7XoAE-vSF.png?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35644, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112587397380943953", "url": "https://x.com/swyx/status/2112587397380943953", "text": "deepseek posted way more alpha on their zhihu page, if you only read twitter you are reading the laowai approved stuff\n\n\"Based on this framework, we have implemented a high-throughput, low-latency large-scale inference service for DeepSeek V4.1 Flash. Currently, the service throughput of a single cluster is 155 trillion tokens/day, and the overall revenue is $38 per card per hour (based on off-peak prices).\"\n\nit costs roughtly $5-10 per gpu hour so depseek is claiming 80% serving margin at THEIR prices lololololol", "name": "swyx", "handle": "swyx", "avatar": "https://pbs.twimg.com/profile_images/2073162797354217472/hNny55eF_200x200.jpg", "likes": 1840, "rts": 114, "replies": 91, "views": 87964, "ts": 1792515060, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFqiZmaIAABXR3.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35642, "rts": 4077, "replies": 1330, "views": 4644113, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792527238, "post_ids": ["2112476496283775135", "2112480719952138301", "2112587397380943953"]}, {"headline": "Anthropic × Citrini Research Design Novel Proteins with an Internal Unreleased Claude Model", "meta": "Explore · Trending · MTS live broadcast", "url": "https://x.com/MTSlive/status/2112571620418355203", "summary": "Citrini Research used an unreleased internal Anthropic model to design novel proteins for a scorpion antivenom target; Anthropic posted on its Science Blog.", "posts": [{"id": "2112571620418355203", "url": "https://x.com/MTSlive/status/2112571620418355203", "text": "SITUATION DETECTED: Investment research firm Citrini Research used an internal unreleased research model from Anthropic to autonomously design novel proteins for a scorpion antivenom.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 472, "rts": 12, "replies": 15, "views": 16842, "ts": 1792511298, "media": [], "quote": null, "reply_to": null}, {"id": "2112609830762668500", "url": "https://x.com/MTSlive/status/2112609830762668500", "text": "SITUATION EXPLAINED: A stock research firm with almost no science background just used Claude to design potential scorpion antivenoms.\n\n• Citrini Research’s 5-person team put up $200K and worked with an internal Anthropic research model\n• Their first request was blocked by biosecurity guardrails, so they ran the prompts in person at Anthropic’s offices\n• Antivenom is still made by injecting horses with scorpion venom, which costs $39M a gallon, about $500 a drop. Scorpions sting 1M+ people a year and kill 3,000+\n• From a 35-page prompt, Claude produced 318K+ designs in 64 hours and picked the best for lab testing\n• The wet lab quoted $85K for 250 samples, which they paid with an American Express\n• 17 of 211 designs bound, covering 4 of 5 toxins, but nobody has tested yet whether they actually block the toxins\n\n@theojaffee: \"This is a signal of the future, that it took them a relatively small amount of time to actually select designs in virtual space. But in order to actually implement them in the real world, it took them like 40 days. Biology is slow.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 429, "rts": 31, "replies": 11, "views": 26914, "ts": 1792520408, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112609728576811008/vid/avc1/640x360/HZHU_8IH2XhtHGa1.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112609728576811008/vid/avc1/1280x720/kpVzbDzP8JBR6qrv.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112609728576811008/img/mucV1WGPa7EyLFDu.jpg", "dur": 222}], "quote": {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5779, "rts": 455, "replies": 393, "views": 1192358, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112552475471360188", "url": "https://x.com/stevehou/status/2112552475471360188", "text": "Congrats to the @AnthropicAI and @citrini teams for this extraordinary novel achievement! No better time than now for tech bros to get stung by scorpions in addition to chain-smoking! If you don't intentionally get stung by a scorpion on your next hike, are you even AGI-piled?", "name": "Steve Hou", "handle": "stevehou", "avatar": "https://pbs.twimg.com/profile_images/1905914798300073984/stc3q7RB_200x200.jpg", "likes": 189, "rts": 14, "replies": 8, "views": 12889, "ts": 1792506734, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFKpHHXIAA8L8x.jpg?name=orig"}], "quote": {"id": "2112543436591018106", "url": "https://x.com/amirshanehsaz/status/2112543436591018106", "text": "🦂 This was a very fun collaboration with the team @citrini! Thank you to @TwistBioscience and @adaptyvbio for the rapid turnaround on experimental validation and to Susana Vázquez Torres (@CNIOStopCancer), Tim Jenkins (@DTUtweet ), and Dan Bedinger (@carterra_bio) for their thoughtful review.\n\nRead more in our blog post: https://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Amir Shanehsazzadeh", "handle": "amirshanehsaz", "avatar": "https://pbs.twimg.com/profile_images/1469848771303378946/HiHJVs70_200x200.jpg", "likes": 225, "rts": 20, "replies": 10, "views": 42029, "ts": 1792504579, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112541418329694208/vid/avc1/1280x720/h2UbO95knYIA0eb5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112541418329694208/vid/avc1/3840x2160/9hltcERl8kPoLsvv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112541418329694208/img/bWwbSs3TLx89nFj9.jpg", "dur": 60}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792527238, "post_ids": ["2112571620418355203", "2112609830762668500", "2112552475471360188"]}, {"headline": "Ornith-1.5-122B Launch: 'No Tradeoff Between Strong and Fast'", "meta": "Explore · Trending · Technology", "url": "https://x.com/ornith_/status/2112553477457268799", "summary": "Ornith announced Ornith-1.5-122B, claiming frontier-level capability with high inference efficiency, reportedly on a single NVIDIA DGX card.", "posts": [{"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112565310519746660", "url": "https://x.com/I_amShiti/status/2112565310519746660", "text": "Frontier-level performance on a single NVIDIA DGX card is a big deal. \n\nOrnith-1.5-122B could make powerful AI workflows more accessible while delivering the speed and efficiency developers need.", "name": "Kuria | AI", "handle": "I_amShiti", "avatar": "https://pbs.twimg.com/profile_images/2036423514660708352/PtFecw86_200x200.jpg", "likes": 83, "rts": 59, "replies": 24, "views": 8162, "ts": 1792509794, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2374, "rts": 432, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792527238, "post_ids": ["2112553477457268799", "2112565310519746660"]}, {"headline": "ChatGPT Adds Locked Chats for PIN-Protected Privacy", "meta": "Today's News · 6 hours ago · News · 662 posts (tick 663 at latest reload)", "url": "https://x.com/i/trending/2112639715870466493", "summary": "RECOVER_FROM_PRIOR_SESSION_ONLY — X's Grok summary was captured in the prior session but was not re-read in this run. Trend surfaced in Today's News sidebar (news_sidebar_article_QWlUcmVuZDoyMTEyNjM5NzE1ODcwNDY2NDkz). Re-capture recommended on next fire via https://x.com/i/trending/2112639715870466493.", "posts": [{"id": "2112597766333673624", "url": "https://x.com/ChatGPT/status/2112597766333673624", "text": "Keep sensitive conversations out of view with Locked Chats in ChatGPT.\n\nMove chats out of your regular history and search into a protected space you can unlock with a PIN on web and desktop, or a PIN, Face ID, Touch ID, or device unlock on supported mobile devices.\n\nNew messages sent in locked chats won't update the memory used in your regular chats.\n\nRolling out starting today to Free, Go, Plus, Pro, Business, Enterprise, and Edu plans.", "name": "ChatGPT", "handle": "ChatGPT", "avatar": "https://pbs.twimg.com/profile_images/2081980424666935296/qU5G7mQg_200x200.jpg", "likes": 3819, "rts": 246, "replies": 241, "views": 278383, "ts": 1792517532, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112597507310305280/vid/avc1/1280x720/_Yq-Cx7meVgtTpyo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112597507310305280/vid/avc1/3840x2160/TXTTh_md33ZoDYON.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVF0k2Da4AAaDmx.png", "dur": 40}], "quote": null, "reply_to": null}, {"id": "2112605106642600283", "url": "https://x.com/testingcatalog/status/2112605106642600283", "text": "OPENAI 🔥: Locked Chats in ChatGPT are rolling out to Free, Go, Plus, Pro, Business, Enterprise, and Edu plans.\n\nUsers can move chats into a protected space under a PIN on web and desktop, or a PIN, Face ID, Touch ID, or device unlock.\n\nLocked in 👀👀👀", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 522, "rts": 15, "replies": 39, "views": 26696, "ts": 1792519282, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112597507310305280/vid/avc1/1280x720/_Yq-Cx7meVgtTpyo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112597507310305280/vid/avc1/3840x2160/TXTTh_md33ZoDYON.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVF0k2Da4AAaDmx.png", "dur": 40}], "quote": null, "reply_to": null}], "notes": "Only 2 of 3 top-post status URLs captured. Summary not re-verified in this run.", "captured": 1792550214, "post_ids": ["2112597766333673624", "2112605106642600283"]}, {"headline": "DeepSeek Open-Sources DeepInfer, In-House Inference Framework Powering DeepSeek-V4.1-Flash", "meta": "Explore · Trending · Technology · DeepInfer / DeepSeek (single-keyword tech trends; clicking either opens a search results page — no /i/trending/<id>, no post count, no X Grok summary. Both trends surface the same top post, so this covers the combined DeepInfer+DeepSeek trend rather than duplicating).", "url": "https://x.com/search?q=DeepInfer&src=trend_click&vertical=trends", "summary": "DeepSeek released DeepInfer, its in-house large-scale inference framework, now fully open source under the Apache-2.0 license. The framework powers DeepSeek-V4.1-Flash in production at scale with high throughput and low latency. DeepSeek is sharing the weights (MIT) alongside attention kernels including FlashMLA (580 TFLOPS on H800) and the DeepEP component, and disclosed operational scale: a single cluster serves 155 trillion tokens/day, generating roughly $38 of revenue per GPU-hour at off-peak pricing. The release has drawn fast responses from the inference ecosystem — vLLM announced it can reproduce DeepSeek's decode performance within 6% using Wide-EP and EPLB, matching roughly $39/gpu/hr revenue. (Summary composed from the top post @deepseek_ai/status/2112476496283775135 official announcement and surrounding top posts observed on the DeepInfer trend-click search page. X renders NO Grok 'Summary of this trend' block for single-keyword tech trends, so no X-authored summary is available to quote.)", "posts": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112653788574339075", "url": "https://x.com/superalesha/status/2112653788574339075", "text": "DeepSeek just published the price of a token, and it should make you angry.\n\nFrom their own DeepInfer docs: 1 cluster serves 155 trillion tokens a day, at $38 of revenue per GPU-hour, and thats at off-peak prices. Their API is $0.30 per million input tokens and $1.20 per million output at peak.\n\nYuchen Jin did the math: even if they rented B300s at $7 an hour, thats about 82% gross margin. Other estimates go higher.\n\nSo cheap AI is not charity and it is not \"dumping\". At these prices serving a frontier-class model is a very profitable business, if your inference stack is good enough.\n\nNow remember every time a US lab told you that intelligence is expensive. That $200 a month is a fair price. That limits exist because compute is scarce.\n\nPart of that is true. Part of it is a business model built on you not knowing what a token actually costs.\n\nDeepSeek just showed everyone the numbers and gave away the engine. Every inference company can now compete on price with the same software. Thats how AI gets cheap for everyone.", "name": "Alexey Fateev", "handle": "superalesha", "avatar": "https://pbs.twimg.com/profile_images/2074424168179769344/pBJWRZvX_200x200.jpg", "likes": 2595, "rts": 183, "replies": 73, "views": 126543, "ts": 1792530889, "media": [], "quote": {"id": "2112591074409742733", "url": "https://x.com/Yuchenj_UW/status/2112591074409742733", "text": "“A single cluster currently serves 155 trillion tokens/day, generating $38 in revenue per GPU-hour (at off-peak pricing).”\n\nHuge flex from DeepSeek. Not only did they open-source their inference engine, but they also open-sourced their revenue numbers.\n\nThey didn't disclose which GPUs they're using here, but DeepInfer supports both NVIDIA Blackwell and Huawei Ascend.\n\nEven assuming they're renting B300s at $7 per GPU-hour, that's ~82% gross margin.", "name": "Yuchen Jin", "handle": "Yuchenj_UW", "avatar": "https://pbs.twimg.com/profile_images/1319081238439751681/kCcqnwoF_200x200.jpg", "likes": 2766, "rts": 182, "replies": 97, "views": 270476, "ts": 1792515936, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFtIWAaQAAy6-k.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112471106426900677", "url": "https://x.com/tianyi/status/2112471106426900677", "text": "DeepSeek just open sourced its high-performance, large-scale inference framework DeepInfer in Apache-2.0 license.\n\nhttps://github.com/deepseek-ai/DeepInfer\n\nSupported features:\n\n- Optimized kernels, model and sampler runtime\n- Parallelism: Attention DP / balanced CP, MoE EP + EPLB\n- DSpark and confidence-scheduled verification\n- SWA bounded replay\n- Asynchronous scheduling (zero-overhead batch scheduler)\n- Batch-invariant inference\n- Deterministic sampling\n- Structured output", "name": "Tianyi Cui", "handle": "tianyi", "avatar": "https://pbs.twimg.com/profile_images/378800000650737082/b849b67d6470fafe8b3deb2ae97acfda_200x200.jpeg", "likes": 2486, "rts": 199, "replies": 201, "views": 264168, "ts": 1792487334, "media": [], "quote": null, "reply_to": null}], "notes": "Top post (DeepSeek official DeepInfer announcement, 16h ago, 5795 reposts / 33.5k likes / 4M+ views at capture). Second top post: Alexey Fateev @superalesha on the $38/GPU-hr disclosure (4h ago at capture, repost of the DeepInfer pricing disclosure). Third top post: Tianyi Cui @tianyi Apache-2.0 deep-link to github.com/deepseek-ai/DeepInfer (16h ago). Alternative third: vLLM @vllm_project/status/2112703311933747347 (1h ago, vLLM matching DeepInfer decode within 6%) was preferred-ecologically but Tianyi's post ranks higher in the trend click's Top tab; swapped in for the trend-ordered top 3. The DeepSeek trend click (/search?q=DeepSeek&src=trend_click&vertical=trends) surfaces the identical @deepseek_ai/status/2112476496283775135 top post and is therefore a duplicate trend — not emitted as a separate kept item.", "captured": 1792550214, "post_ids": ["2112476496283775135", "2112653788574339075", "2112471106426900677"]}, {"headline": "Respan Launches Open-Source AI Gateway Connecting LLMs, Images, Video, Realtime Voice and MCP Tools", "meta": "Explore · Trending · Technology · Apache 2.0", "url": "https://x.com/search?q=Apache%202.0&src=trend_click&vertical=trends", "summary": "Respan OSS Gateway connects LLMs, images, video, realtime voice and MCP tools.", "posts": [{"id": "2112589739752837309", "url": "https://x.com/RespanAI/status/2112589739752837309", "text": "Respan OSS Gateway: the last AI gateway you ever need.\n\nBecause it can connect anything: LLMs, images, video, realtime voice, and MCP tools like web search and long-term memory, all through one endpoint. Each one is just a plugin you switch on.\n\nAgainst LiteLLM on the same machine:\n - 0.08 ms vs 5.9 ms added latency (78x less)\n - 61,062 vs 1,348 requests/s with 50 in flight (45x more; LiteLLM on 14 workers)\n - 33 MB vs 494 MB memory (15x less; LiteLLM on 1 worker)\n\nFully written in Rust. MIT/Apache-2.0.", "name": "Respan", "handle": "RespanAI", "avatar": "https://pbs.twimg.com/profile_images/2027070589756940288/1tWZSpNu_200x200.jpg", "likes": 129, "rts": 18, "replies": 17, "views": 10341, "ts": 1792515618, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1280x720/Vcevcs1-ZMZLV7oo.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1920x1080/o7SYrt6EbEVRDm_V.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589708589158400/img/BRkz-jytt9YRMCOW.jpg", "dur": 30}], "quote": null, "reply_to": null}], "captured": 1792529266, "post_ids": ["2112589739752837309"]}, {"headline": "Developers Build Shared Memory for AI Coding Agents", "meta": "Today's News · Other/News · 151 posts", "url": "https://x.com/i/trending/2112645323529277522", "summary": "AI coding agents (Claude Code, Cursor, Codex) were siloed; tools such as Beacon from Asymptote Labs capture activity across 20+ platforms to make prompts/edits/workflows searchable; solutions like EverOS Cloud, Databricks' MemCurrent, and decentralized Lighthouse Memory boost performance (reportedly tripling pass rates in benchmarks) while flagging risks like credential leaks — letting knowledge follow developers.", "posts": [{"id": "2112546384331313274", "url": "https://x.com/akshay_pachaar/status/2112546384331313274", "text": "I gave Claude Code, Codex, and Cursor a self-improving, shared MEMORY.\n\nNow my coding agents learn from each other, and their knowledge follows me wherever I work.\n\nCoding agents work in silos. Your corrections in Cursor don't carry over to Claude Code, and skills built in Codex don't automatically transfer to other harnesses.\n\nSo switching tools often means starting from scratch.\n\nWhat if every coding agent could learn from everything you've already done?\n\nI invited @jqdsouza, co-founder of Asymptote Labs, to show me how to make this possible with Beacon, a 100% open-source memory layer for coding agents.\n\nWe set it up live, explored real coding sessions, and watched Beacon turn past work into reusable knowledge.\n\nHere's what I learned:\n\n1. One memory layer for 20+ coding agents.\n\nBeacon captures activity across Claude Code, Cursor, Codex, and 20+ harnesses using OpenTelemetry, hooks, and local session files. Everything gets normalized into a single format, regardless of which agent you're using.\n\n2. Your entire coding history becomes searchable.\n\nEvery prompt, tool call, command, file change, and response is captured in a structured trace. Instead of losing valuable context when a session ends, you build a searchable history of everything your agents have done.\n\n3. Switch agents without starting over.\n\nHit your usage limit in Cursor? Open Claude Code and ask it to continue your latest Cursor session. Beacon retrieves the relevant context in milliseconds so your next agent can pick up where the last one left off.\n\n4. Your agents learn from your past work.\n\nThis is where things get interesting.\n\nBeacon identifies repeated workflows and turns them into reusable skills. In our demo, it discovered a recurring UI development workflow and generated a skill containing the exact dev server commands, screenshot steps, and deployment instructions.\n\nYou teach one agent something once. Every other agent can benefit.\n\n5. Stop accumulating skills nobody uses.\n\nHave 100 skills but only use five? Beacon analyzes actual usage across thousands of sessions and identifies skills worth keeping, combining, or removing.\n\nYour agent's memory gets more useful, not just bigger.\n\n6. Security rules that follow you across every harness.\n\nBeacon includes hundreds of detection rules that work across agents. It can identify risky behavior, including sequences where an agent reads sensitive credentials and then makes an outbound network request.\n\n7. It even caught a real credential leak.\n\nWhile reviewing Justin's actual Cursor history, Beacon surfaced an incident where part of a production database password had been sent to a model provider.\n\nThat's the power of having visibility into what your agents are actually doing.\n\n8. One prompt to get started. Completely open source.\n\nPaste a setup prompt into your coding agent and you're off. Keep everything local on your machine, or use Beacon Cloud for free.\n\nIf you're juggling multiple coding agents, you need to check this out.\n\nDrop a like and share it with someone facing the same issue.\n\nBeacon on GitHub: http://github.com/Asymptote-Labs/agent-beacon\n\n(don't forget to star 🌟)\n\nEnjoy the episode.\n\nCheers!", "name": "Akshay 🚀", "handle": "akshay_pachaar", "avatar": "https://pbs.twimg.com/profile_images/1578327351544360960/YFpWSWIX_200x200.jpg", "likes": 200, "rts": 20, "replies": 82, "views": 16461, "ts": 1792505281, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112544725077282817/vid/avc1/1280x720/V1lKyDMKAykmR56I.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112544725077282817/vid/avc1/1920x1080/WIBS_24JrKAMAtBk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112544725077282817/img/MRFf3s76n2L_J4Hk.jpg", "dur": 1741}], "quote": null, "reply_to": null}, {"id": "2112608072770396658", "url": "https://x.com/LetsGrowithAI/status/2112608072770396658", "text": "New engineers often waste days hunting for “why we made that architecture choice” or “what we already tried last quarter.”\n\nI tested EverOS Cloud with one real task: saving and retrieving context from a past troubleshooting note.\n\nI connected through the EverOS Cloud console and used the Chat Interface Playground. I saved a short note about a previous interface issue (“login button failed on mobile after the last deploy — fixed by clearing cache and checking the auth header”).\n\nBefore starting a related follow-up task, I retrieved that context. The returned memory included the earlier issue and the fix that worked. I then checked Memory Bank to browse the saved entry.\n\nIn this test I demonstrated saving and retrieving User Memory. I did not create an agent Case or Skill, so I am distinguishing those capabilities from what I verified. Memory Bank was used only for browsing; correcting, deleting, or rating entries is done through the API.\n\nWhat I observed: the saved context came back clearly when retrieved, which makes it practical to carry relevant history into the next task instead of starting from zero.\n\nSubscribe to Pro now and get 3× your monthly usage allowance for 6 months → https://everos.evermind.ai", "name": "AI Girl", "handle": "LetsGrowithAI", "avatar": "https://pbs.twimg.com/profile_images/2067509876688109568/eiqgq2Zj_200x200.jpg", "likes": 121, "rts": 78, "replies": 61, "views": 11790, "ts": 1792519989, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112608021226598400/vid/avc1/1488x720/FXn0_TtIrwg_MbQ1.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112608021226598400/vid/avc1/2232x1080/j646dsvgCZTD1w2y.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112608021226598400/img/J6fC3KU551RLNWeI.jpg", "dur": 25}], "quote": null, "reply_to": null}, {"id": "2112598568624165296", "url": "https://x.com/databricks/status/2112598568624165296", "text": "Introducing MemCurrent, a persistent memory architecture designed to help production agents stop starting from zero.\n\nMemCurrent combines episodic memory with derived memory across three access patterns:\n\n• Plugins to log and load context automatically\n• Tools the agent calls on demand\n• An offline “dreaming” pipeline that consolidates memory in the background\n\nAgents carry forward user preferences, prior corrections, metric definitions and successful workflows instead of rediscovering them every session.\n\nOn our internal benchmark built from real enterprise data, MemCurrent triples the agent's pass rate while using 31% fewer tokens and running 26% faster. It's built into Agent Bricks' Memory offering and already powers memory in Genie.\n\nRead the research: https://www.databricks.com/blog/memcurrent-designing-persistent-memory-production-agents?utm_source=twitter&utm_medium=organic-social", "name": "Databricks", "handle": "databricks", "avatar": "https://pbs.twimg.com/profile_images/2070268421615333376/SZUvhQiQ_200x200.jpg", "likes": 182, "rts": 22, "replies": 13, "views": 21694, "ts": 1792517723, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112598477431578624/vid/avc1/1280x720/smO0-OBExwy6PXT7.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112598477431578624/vid/avc1/1920x1080/0bdpPkH6c0s8r-7_.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVF1M4CW0AAT8GS.jpg", "dur": 80}], "quote": null, "reply_to": null}], "captured": 1792530674, "post_ids": ["2112546384331313274", "2112608072770396658", "2112598568624165296"]}, {"headline": "NVIDIA Open-Sources Flora Toolkit for Robot Training Data", "meta": "Today's News · Trending now · News · 100 posts", "url": "https://x.com/i/trending/2112645324045250691", "summary": "Flora, announced by NVIDIA's Jim Fan, includes models like Flora-TempSeg for breaking videos into timestamped actions and Flora-Captioner for adding natural language instructions. It generates progress rewards, outcome scores, and failure evaluations to refine data for reinforcement learning and real-world benchmarks. Already labeling 200,000 hours of video daily in NVIDIA's systems, Flora matches high-end performance on both human and robot footage while slashing costs by about 125 times compared to rivals like Astra. Researchers praise it for advancing affordable data infrastructure toward capable, general-purpose robots.", "posts": [{"id": "2112597587987689912", "url": "https://x.com/DrJimFan/status/2112597587987689912", "text": "We built a robotics data engine with Astra-level performance at 125x lower cost. And we are open-sourcing the weights today! Introducing Flora, a suite of open models to parse the physical world and turn raw footage into rich training signals. \n\nFlora already powers our in-house data engine, labeling 200K hours of videos a day on 500 GPUs. We created it to scale the frontier for robot learning. Now you own the weights too. \n\nFlora gives you:\n\n- High-quality, timestamped captions to curate and filter human egocentric and robot data;\n- Dense progress rewards for quality control and RL post-training;\n- Rubrics scoring for real-world benchmarking\n\nTry it today, links in thread:", "name": "Jim Fan", "handle": "DrJimFan", "avatar": "https://pbs.twimg.com/profile_images/1554922493101559808/SYSZhbcd_200x200.jpg", "likes": 1131, "rts": 126, "replies": 109, "views": 68578, "ts": 1792517489, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589725337083904/vid/avc1/1280x720/DgArsymrx3Bk5q70.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112589725337083904/vid/avc1/1920x1080/ch1ZmCQbS8jTxRNm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589725337083904/img/4Fy5XFx6jbgKIYgv.jpg", "dur": 67}], "quote": null, "reply_to": null}, {"id": "2112590210840281500", "url": "https://x.com/yunzeman/status/2112590210840281500", "text": "Introducing Flora, an open model suite for scaling robotics data engines.\n\nIt watches robot and human video and annotate what happened (timestamped instructions) and how well it went (rewards and failure reasons).\n\n🔗 https://research.nvidia.com/labs/gear/flora/\n\nWe use it to train NVIDIA GR00T. 🧵", "name": "Yunze Man", "handle": "yunzeman", "avatar": "https://pbs.twimg.com/profile_images/1996643057417310212/Z-TT9BDD_200x200.jpg", "likes": 125, "rts": 28, "replies": 12, "views": 14099, "ts": 1792515730, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588539208863744/vid/avc1/1280x720/inKlesAy6khdYBfi.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588539208863744/vid/avc1/1920x1080/juLtT7P2UmNbbAdJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588539208863744/img/YK6TtWvw_ZSX5Z1Y.jpg", "dur": 67}], "quote": null, "reply_to": null}, {"id": "2112593246790590530", "url": "https://x.com/Haoyu_Xiong_/status/2112593246790590530", "text": "After seeing Astra's strong reasoning capabilities in robotics, I'm more convinced that we shall not bake \"language following / reasoning\" into low-level action models, i.e., VLAs.", "name": "Haoyu Xiong", "handle": "Haoyu_Xiong_", "avatar": "https://pbs.twimg.com/profile_images/1566676227687170048/zSJA-NGf_200x200.jpg", "likes": 49, "rts": 0, "replies": 0, "views": 4113, "ts": 1792516454, "media": [], "quote": {"id": "2111143189222404427", "url": "https://x.com/du_yilun/status/2111143189222404427", "text": "Robotics has spent years scaling demonstration data and model size. What happens when we scale EXPLORATION for robot agents?\n\nWe're incredibly excited to share RAX, an agentic robotics system that learns by scaling online exploration.\n\nA coding agent connects directly to the robot’s perception and control APIs, learns from feedback, and builds programs that perceive, plan, and act. The model stays frozen. As exploration scales, the agent improves its programs and builds up reusable skills.\n\nThe results:\n   • ZERO teleoperation or action demonstrations on real robots—from insertion with 0.1 mm clearance and air-fryer manipulation to deformable objects and long-horizon mobile whole-body control.\n    • +37 percentage points on average over leading learned policies across five simulation benchmarks: RoboDojo, BEHAVIOR-1K, HumanoidArena, DexJoCo’s bimanual tasks, and LIBERO-Pro.\n    • One framework spanning single-arm, bimanual, dexterous, humanoid, and mobile robots, with new embodiments connected through APIs.\n\nThe craziest part: on each real-world embodiment, going from scratch to mastering the tasks took roughly two hours. No teleop. No model finetuning.\n\nWe’re open-sourcing the full framework AND every experiment session. We can’t wait to see what people build with it!\n\nProject + sessions: https://robot-agent-exploration.com/\nPaper: https://assets.robot-agent-exploration.com/paper/rax.pdf\nGitHub: N\n\nProject fully led by @RunhanH and @xczhangxx who are absolutely awesome.\n\nHow it works, experiments, and robot videos below 🧵\n\n(1/N)", "name": "Yilun Du", "handle": "du_yilun", "avatar": "https://pbs.twimg.com/profile_images/1851462402413305856/zKEpDnwx_200x200.jpg", "likes": 551, "rts": 102, "replies": 34, "views": 59805, "ts": 1792170734, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111117912194826240/vid/avc1/1280x720/sYHQCeKGzE0VzWrx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111117912194826240/vid/avc1/1920x1080/wunQVw_ce0sHSKR3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111117912194826240/img/JQ3Px_a5V1dVxUgB.jpg", "dur": 155}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792532456, "post_ids": ["2112597587987689912", "2112590210840281500", "2112593246790590530"]}, {"headline": "DeepSeek Open-Sources DeepInfer Inference Framework", "meta": "Explore · Trending · Technology · DeepInfer", "url": "https://x.com/search?q=%23DeepInfer&src=hashtag_click", "summary": "DeepSeek open-sourced DeepInfer, the in-house, high-performance, large-scale inference framework that powers DeepSeek-V4.1-Flash in production, under Apache 2.0. The official DeepSeek post (1.1K replies, 5.2K reposts, ~30K likes, 3.3M views) says it brings high throughput and low latency and shares the production stack to help the community lower compute costs, reduce energy use, and make AI more accessible. Coverage and threads (e.g., from @askarthemass, @qz, @yuhasbeentaken) note it currently targets offline inference and supports both NVIDIA SM100 GPUs and Huawei Ascend 950 NPUs, and that DeepSeek frames a single V4.1 Flash cluster as able to serve 155 trillion tokens; the release is positioned as exposing the inference layer rather than another model drop.", "posts": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112504870968365205", "url": "https://x.com/askarthemass/status/2112504870968365205", "text": "DeepSeek Just Open-Sourced Its AI Engine: DeepInfer\n\nIt powers DeepSeek-V4.1-Flash in production, now Apache 2.0. The catch: offline inference only for now.\n\nSource: @deepseek_ai\nRepo: https://github.com/deepseek-ai/DeepInfer\n\n#DeepSeek #DeepInfer #AI #OpenSource", "name": "Askar 🚀(Angular) 🚀", "handle": "askarthemass", "avatar": "https://pbs.twimg.com/profile_images/1994720086205288448/izoH0odt_200x200.jpg", "likes": 1, "rts": 0, "replies": 0, "views": 96, "ts": 1792495384, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112504805486649344/vid/avc1/720x1280/CAvJQAOHnecAXetI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112504805486649344/vid/avc1/1080x1920/SuT5t4byPnsEtlRn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112504805486649344/img/W9kMgv3Dl1l9JZBs.jpg", "dur": 55}], "quote": null, "reply_to": null}, {"id": "2112540863922311420", "url": "https://x.com/qz/status/2112540863922311420", "text": "DeepSeek Just Gave Away Its AI Playbook\n\nDeepSeek is open-sourcing DeepInfer, the inference framework powering its large-scale AI production services, a move that exposes techniques most companies guard closely. The relea\n\nhttps://qz.com/deepseek-open-source-deepinfer-inference-software-ai-102026\n\n#DeepSeek #DeepInfer #OpenSource", "name": "Quartz", "handle": "qz", "avatar": "https://pbs.twimg.com/profile_images/1238278574152572929/HgSD467J_200x200.jpg", "likes": 0, "rts": 0, "replies": 1, "views": 589, "ts": 1792503965, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFAt_tW0AAS0h6.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792530674, "post_ids": ["2112476496283775135", "2112504870968365205", "2112540863922311420"]}]);